-- Synthetic demo evidence for the six SYNTHETIC_SCENARIOS (labelled is_synthetic).
-- Generated from contract-validated fixtures, so every row passes the read models.
-- It gives the map, dashboard and timeline content before the live agents are
-- wired in. Live agents may add more findings; nothing here is ever updated.




-- The fusion recommendation, applied as the runtime would. Never "reviewed".
update public.investigations set status = 'needs_human_review', review_priority = 'high' where id = '00000000-1923-4596-a095-774098c7d58b' and status <> 'reviewed';
update public.investigations set status = 'insufficient_evidence', review_priority = 'low' where id = '00000000-09fe-4107-b776-6dd00f9c3170' and status <> 'reviewed';
update public.investigations set status = 'investigating', review_priority = 'medium' where id = '00000000-0b9a-4749-91c0-8a00faa295dd' and status <> 'reviewed';
update public.investigations set status = 'needs_human_review', review_priority = 'medium' where id = '00000000-0d80-4774-bb4d-26102d4b14fe' and status <> 'reviewed';
update public.investigations set status = 'needs_human_review', review_priority = 'low' where id = '00000000-1653-4361-8829-3801c69d3012' and status <> 'reviewed';
update public.investigations set status = 'needs_human_review', review_priority = 'medium' where id = '00000000-1146-409b-8d51-0ea14dfbfa8f' and status <> 'reviewed';
