insert into public.agent_findings (id, investigation_id, report_id, agent_id, created_at, evidence_ids, assessment, strength, reason_codes, explanation, limitations, limitation_notes, recommendation, is_synthetic)
values
  ('00000000-0a45-417a-be76-c45112e8eed4', '00000000-1923-4596-a095-774098c7d58b', null, 'satellite', '2026-11-07T09:15:00.000Z', array['00000000-1dcd-49b7-80ee-b611ea161fe3']::uuid[], 'supports', 'moderate', array['thermal_anomaly_nearby']::text[], 'A VIIRS thermal anomaly 0.6 km from the reported area at 08:50 UTC, before the report. A thermal anomaly is not a confirmed fire.', array['synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-046e-449f-8a23-51f199e5e426', '00000000-1923-4596-a095-774098c7d58b', null, 'weather', '2026-11-07T09:15:00.000Z', array['00000000-015b-491b-9b2d-3741e1246cd2']::uuid[], 'context', null, array['dry_or_windy_conditions']::text[], 'Modelled conditions were dry (34% humidity) and windy (27 km/h from the south-west). Context only.', array['weather_is_context_only', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-16cb-4e85-a97d-2cd1d992b436', '00000000-1923-4596-a095-774098c7d58b', '00000000-106e-47a9-a6eb-db11ac53887f', 'witness', '2026-11-07T09:16:00.000Z', array['00000000-106e-47a9-a6eb-db11ac53887f']::uuid[], 'inconclusive', null, array['witness.single_report']::text[], 'One report so far. No independent witness has corroborated it.', array['human_report_unverified', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-197a-4491-8613-cc60080afc00', '00000000-1923-4596-a095-774098c7d58b', null, 'fusion', '2026-11-07T09:18:00.000Z', array['00000000-0a45-417a-be76-c45112e8eed4']::uuid[], 'context', null, array['fusion.status.needs_human_review', 'fusion.priority.high']::text[], 'A satellite thermal anomaly near the report supports it; weather is context only; the report is not yet independently corroborated. A human should review this first.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"needs_human_review","reviewPriority":"high","independentSourceCount":1,"supportingFindingIds":["00000000-0a45-417a-be76-c45112e8eed4"],"contradictingFindingIds":[],"evidenceGaps":[],"possibleDuplicateReportIds":[]}'::jsonb, true),
  ('00000000-0b51-4d7f-b1ab-0b10f796df11', '00000000-09fe-4107-b776-6dd00f9c3170', '00000000-147e-4fbf-9e3e-fea1cf9c16c3', 'vision', '2026-11-07T09:47:00.000Z', array['00000000-147e-4fbf-9e3e-fea1cf9c16c3']::uuid[], 'contradicts', 'weak', array['no_smoke_like_features_visible']::text[], 'The photo shows a white, diffuse layer over the hill top that resembles low cloud rather than a smoke plume.', array['image_authenticity_unverifiable', 'image_location_unverifiable', 'image_time_unverifiable', 'model_output_uncalibrated', 'synthetic_data']::text[], array['No visible fire indicators in one image is weak evidence; it does not rule out a fire outside the frame.']::text[], null, true),
  ('00000000-08b0-4368-a593-69018aea181d', '00000000-09fe-4107-b776-6dd00f9c3170', null, 'satellite', '2026-11-07T09:47:00.000Z', array['00000000-0982-4fcc-8e1e-ba205f4c1e3f']::uuid[], 'inconclusive', null, array['no_thermal_detection_in_window']::text[], 'No thermal anomaly within 10 km between 06:00 and 09:30 UTC. That is not evidence of no fire.', array['no_detection_is_not_absence', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-0f77-4916-83d5-4230c4eb530c', '00000000-09fe-4107-b776-6dd00f9c3170', null, 'weather', '2026-11-07T09:47:00.000Z', array['00000000-1e6b-4f1d-a540-05f047f99d7c']::uuid[], 'context', null, array['recent_precipitation']::text[], 'Modelled conditions were wet and near-saturated (96% humidity, 3.2 mm in 24 h). Context only.', array['weather_is_context_only', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-0ade-415f-a4be-8ab011b58a47', '00000000-09fe-4107-b776-6dd00f9c3170', null, 'fusion', '2026-11-07T09:49:00.000Z', array['00000000-0b51-4d7f-b1ab-0b10f796df11']::uuid[], 'context', null, array['fusion.status.insufficient_evidence', 'fusion.priority.low']::text[], 'The photo looks more like low cloud than smoke and nothing else supports the report. Low priority, but a human can still check.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"insufficient_evidence","reviewPriority":"low","independentSourceCount":0,"supportingFindingIds":[],"contradictingFindingIds":["00000000-0b51-4d7f-b1ab-0b10f796df11"],"evidenceGaps":["No satellite detection, which is not evidence of no fire."],"possibleDuplicateReportIds":[]}'::jsonb, true),
  ('00000000-1848-4a85-93e7-4b60afbdd6bd', '00000000-0b9a-4749-91c0-8a00faa295dd', null, 'satellite', '2026-11-07T10:23:00.000Z', array['00000000-1ceb-41fa-9ea8-8b41a9abf35a']::uuid[], 'inconclusive', null, array['satellite_pass_gap']::text[], 'The last satellite pass over this area was at 08:30 UTC, before the 10:15 report. No data yet, which is unknown, not negative.', array['no_detection_is_not_absence', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-1468-4e61-be9a-1b41d3c1f74d', '00000000-0b9a-4749-91c0-8a00faa295dd', null, 'weather', '2026-11-07T10:23:00.000Z', array['00000000-04f4-4685-b534-4020bad63721']::uuid[], 'context', null, array['dry_or_windy_conditions']::text[], 'Modelled conditions were dry with a moderate breeze. Context only.', array['weather_is_context_only', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-0118-4c2e-93b3-37c010b6e271', '00000000-0b9a-4749-91c0-8a00faa295dd', '00000000-0d26-4143-b8e1-aff19fe18752', 'witness', '2026-11-07T10:24:00.000Z', array['00000000-0d26-4143-b8e1-aff19fe18752']::uuid[], 'inconclusive', null, array['witness.single_report']::text[], 'One report so far. No independent witness has corroborated it.', array['human_report_unverified', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-1f2d-44ad-978f-b660715924f7', '00000000-0b9a-4749-91c0-8a00faa295dd', null, 'fusion', '2026-11-07T10:25:00.000Z', '{}'::uuid[], 'context', null, array['fusion.status.investigating', 'fusion.priority.medium']::text[], 'A credible report with no satellite pass since before it was seen. Still investigating; the gap is not counted against the report.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"investigating","reviewPriority":"medium","independentSourceCount":0,"supportingFindingIds":[],"contradictingFindingIds":[],"evidenceGaps":["No FIRMS pass since 08:30 UTC; the next pass is expected this afternoon."],"possibleDuplicateReportIds":[]}'::jsonb, true),
  ('00000000-04e7-43e5-8773-16b01162e532', '00000000-0d80-4774-bb4d-26102d4b14fe', null, 'satellite', '2026-11-07T10:58:00.000Z', array['00000000-0e96-4c5b-9a39-f2217d32f404']::uuid[], 'supports', 'weak', array['thermal_anomaly_nearby']::text[], 'A low-confidence VIIRS anomaly 1.4 km away at 10:40 UTC. Weak support; not a confirmed fire.', array['synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-0e57-41e2-a53f-54319f787577', '00000000-0d80-4774-bb4d-26102d4b14fe', null, 'weather', '2026-11-07T10:59:00.000Z', array['00000000-0819-47cf-9b5d-def14a0bb27b']::uuid[], 'inconclusive', null, array['source_unavailable']::text[], 'The weather source timed out. Recorded as a gap, not as evidence either way.', array['weather_is_context_only', 'source_unavailable', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-10ae-4513-bd85-9400898a210f', '00000000-0d80-4774-bb4d-26102d4b14fe', '00000000-1fc0-4323-a8e3-55314f1a4833', 'witness', '2026-11-07T10:59:00.000Z', array['00000000-1fc0-4323-a8e3-55314f1a4833']::uuid[], 'inconclusive', null, array['witness.single_report']::text[], 'One report so far. No independent witness has corroborated it.', array['human_report_unverified', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-0d94-41ab-80ab-60b140dc6ef8', '00000000-0d80-4774-bb4d-26102d4b14fe', null, 'fusion', '2026-11-07T11:01:00.000Z', array['00000000-04e7-43e5-8773-16b01162e532']::uuid[], 'context', null, array['fusion.status.needs_human_review', 'fusion.priority.medium']::text[], 'Weak satellite support and an uncorroborated report, with weather missing. A human should review it; the timeout is a gap, not a negative.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"needs_human_review","reviewPriority":"medium","independentSourceCount":1,"supportingFindingIds":["00000000-04e7-43e5-8773-16b01162e532"],"contradictingFindingIds":[],"evidenceGaps":["Weather unavailable (timeout)."],"possibleDuplicateReportIds":[]}'::jsonb, true),
  ('00000000-01f0-4ae5-9502-ba50ad797308', '00000000-1653-4361-8829-3801c69d3012', '00000000-040f-47a7-a7ac-7ba099c9d49f', 'witness', '2026-11-07T11:33:00.000Z', array['00000000-0318-4966-86dd-1d30955a62f6', '00000000-040f-47a7-a7ac-7ba099c9d49f']::uuid[], 'inconclusive', null, array['witness.duplicate_submission', 'possible_duplicate_report']::text[], 'The second report comes from the same reporter as the first, describes the same place and was sent 8 minutes later. It is counted once.', array['human_report_unverified', 'possible_shared_origin', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-002c-4a93-9b64-2bb0c73ec514', '00000000-1653-4361-8829-3801c69d3012', null, 'fusion', '2026-11-07T11:35:00.000Z', '{}'::uuid[], 'context', null, array['fusion.status.needs_human_review', 'fusion.priority.low']::text[], 'Two reports, one person: the witness agent counted them once. Nothing independent supports them yet.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"needs_human_review","reviewPriority":"low","independentSourceCount":0,"supportingFindingIds":[],"contradictingFindingIds":[],"evidenceGaps":["Both reports come from one person: no independent corroboration."],"possibleDuplicateReportIds":["00000000-040f-47a7-a7ac-7ba099c9d49f"]}'::jsonb, true),
  ('00000000-0416-40b0-b783-e4c05ec7ef81', '00000000-1146-409b-8d51-0ea14dfbfa8f', null, 'satellite', '2026-11-07T11:54:00.000Z', array['00000000-18d3-4db2-a05a-db91d7379b90']::uuid[], 'supports', 'moderate', array['thermal_anomaly_nearby']::text[], 'Processed while isolated: a high-confidence VIIRS anomaly 0.5 km away at 11:30 UTC. Not a confirmed fire.', array['synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-11b0-4061-82f9-a001a3425ee6', '00000000-1146-409b-8d51-0ea14dfbfa8f', '00000000-0257-499c-9b8e-9c81906653c9', 'witness', '2026-11-07T11:58:00.000Z', array['00000000-0257-499c-9b8e-9c81906653c9']::uuid[], 'inconclusive', null, array['witness.single_report']::text[], 'One report so far. No independent witness has corroborated it.', array['human_report_unverified', 'synthetic_data']::text[], '{}'::text[], null, true),
  ('00000000-083e-4c0b-aa5d-2071b3fe3483', '00000000-1146-409b-8d51-0ea14dfbfa8f', null, 'fusion', '2026-11-07T11:59:00.000Z', array['00000000-0416-40b0-b783-e4c05ec7ef81']::uuid[], 'context', null, array['fusion.status.needs_human_review', 'fusion.priority.medium']::text[], 'After reconciliation, the satellite finding made while isolated supports the report. A human should review it.', array['model_output_uncalibrated', 'synthetic_data']::text[], '{}'::text[], '{"recommendedStatus":"needs_human_review","reviewPriority":"medium","independentSourceCount":1,"supportingFindingIds":["00000000-0416-40b0-b783-e4c05ec7ef81"],"contradictingFindingIds":[],"evidenceGaps":[],"possibleDuplicateReportIds":[]}'::jsonb, true);
